<?php

declare(strict_types=1);

use Illuminate\Contracts\Console\Kernel;
use Illuminate\Support\Facades\Http;
use Prism\Prism\Audio\TextToSpeechRequest;
use Prism\Prism\Embeddings\Request;
use Prism\Prism\Facades\Prism;

try {
    // CI-only runner for snippets generated by our renderer, never a web endpoint.
    $root = dirname(__DIR__);
    $file = realpath($argv[1] ?? '');
    $provider = $argv[2] ?? '';
    if (PHP_SAPI !== 'cli' || $file === false || dirname(dirname($file)) !== $root
        || ! str_starts_with(basename(dirname($file)), '.provider-setup-check-')
        || preg_match('/^[a-z]+$/D', $provider) !== 1 || basename($file) !== $provider.'.php') {
        throw new RuntimeException('Only owned generated setup snippets may run in this test.');
    }

    require $root.'/vendor/autoload.php';
    $app = require $root.'/bootstrap/app.php';
    $app->make(Kernel::class)->bootstrap();
    Http::preventStrayRequests();
    // Even a regression in fake resolution must not consult a real ADC file.
    config(['prism.providers.vertex.access_token' => 'OWNED_OFFLINE_TEST_CANARY']);
    $fake = Prism::fake();
    ob_start();
    try {
        require $file;
        $output = trim((string) ob_get_contents());
    } finally {
        ob_end_clean();
    }
    $expected = match ($provider) {
        'voyageai' => Request::class,
        'elevenlabs' => TextToSpeechRequest::class,
        'replicate' => \Prism\Prism\Images\Request::class,
        default => \Prism\Prism\Text\Request::class,
    };
    $fake->assertRequest(function (array $requests) use ($expected): void {
        if (count($requests) !== 1) {
            throw new RuntimeException('Expected 1 calls, got '.count($requests));
        }
        if (! $requests[0] instanceof $expected) {
            throw new RuntimeException('Local example used the wrong native request type.');
        }
    });
    $pattern = match ($provider) {
        'voyageai' => '/^\d+ embedding\(s\)$/',
        'elevenlabs' => '/^\d+ audio bytes$/',
        'replicate' => '/^\d+$/',
        default => '/^$/',
    };
    if (preg_match($pattern, $output) !== 1) {
        throw new RuntimeException('Local example did not consume the native response.');
    }
    echo $provider.' native offline snippet PASS'.PHP_EOL;
} catch (Throwable $error) {
    // A registered application exception handler can otherwise render a failed
    // assertion and let PHP exit zero. The caller also requires our PASS marker.
    fwrite(STDERR, $error->getMessage().PHP_EOL);
    exit(1);
}
